use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tokio::net::TcpListener;
use tokio_tungstenite::accept_async;
use futures_util::{StreamExt, SinkExt};
use aes_gcm::{Aes256Gcm, Key, Nonce};
use aes_gcm::aead::{Aead, NewAead};
use rand::RngCore;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize)]
struct Session {
    user_id: u64,
    role: Role,
    token_hash: Vec<u8>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
enum Role {
    User,
    Admin,
}

#[derive(Clone)]
struct EncryptedStore {
    cipher: Aes256Gcm,
    data: Arc<Mutex<HashMap<String, Vec<u8>>>>,
}

impl EncryptedStore {
    fn new(key_bytes: &[u8; 32]) -> Self {
        let key = Key::from_slice(key_bytes);
        let cipher = Aes256Gcm::new(key);
        Self {
            cipher,
            data: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn store_session(&self, session_id: &str, session: &Session) -> Result<(), String> {
        // Use a fresh random nonce per encryption to avoid (key, nonce) reuse.
        let mut nonce_bytes = [0u8; 12];
        rand::thread_rng().fill_bytes(&mut nonce_bytes);
        let nonce = Nonce::from_slice(&nonce_bytes);
        let plaintext = serde_json::to_vec(session).map_err(|e| e.to_string())?;
        let ciphertext = self.cipher.encrypt(nonce, plaintext.as_ref())
            .map_err(|e| e.to_string())?;
        // Prepend the nonce to the stored ciphertext so it can be recovered on load.
        let mut stored = Vec::with_capacity(12 + ciphertext.len());
        stored.extend_from_slice(&nonce_bytes);
        stored.extend_from_slice(&ciphertext);
        self.data.lock().unwrap().insert(session_id.to_string(), stored);
        Ok(())
    }

    fn load_session(&self, session_id: &str) -> Result<Session, String> {
        let data = self.data.lock().unwrap();
        let stored = data.get(session_id).ok_or("Session not found")?;
        if stored.len() < 12 {
            return Err("Corrupt session record".to_string());
        }
        let (nonce_bytes, ciphertext) = stored.split_at(12);
        let nonce = Nonce::from_slice(nonce_bytes);
        let plaintext = self.cipher.decrypt(nonce, ciphertext)
            .map_err(|e| e.to_string())?;
        serde_json::from_slice(&plaintext).map_err(|e| e.to_string())
    }
}

struct AuthzEngine {
    store: EncryptedStore,
}

impl AuthzEngine {
    fn new(store: EncryptedStore) -> Self {
        Self { store }
    }

    fn check_permission(&self, session_id: &str, required_role: &Role) -> Result<bool, String> {
        let session = self.store.load_session(session_id)?;
        Ok(self.role_satisfies(&session.role, required_role))
    }

    fn role_satisfies(&self, user_role: &Role, required: &Role) -> bool {
        match (user_role, required) {
            (Role::Admin, _) => true,
            (Role::User, Role::User) => true,
            (Role::User, Role::Admin) => false,
        }
    }

    fn elevate_session(&self, session_id: &str, target_session_id: &str) -> Result<(), String> {
        let requestor = self.store.load_session(session_id)?;
        if requestor.role != Role::Admin {
            return Err("Insufficient privileges".to_string());
        }
        let mut target = self.store.load_session(target_session_id)?;
        target.role = Role::Admin;
        self.store.store_session(target_session_id, &target)
    }
}

#[derive(Deserialize)]
struct WsMessage {
    action: String,
    session_id: String,
    payload: Option<serde_json::Value>,
}

async fn handle_message(authz: &AuthzEngine, msg: &WsMessage) -> String {
    match msg.action.as_str() {
        "read_secrets" => {
            match authz.check_permission(&msg.session_id, &Role::Admin) {
                Ok(true) => "{\"status\": \"ok\", \"data\": \"TOP_SECRET_DATA\"}".to_string(),
                Ok(false) => "{\"status\": \"denied\"}".to_string(),
                Err(e) => format!("{{\"status\": \"error\", \"msg\": \"{}\"}}", e),
            }
        }
        "elevate" => {
            let target = msg.payload.as_ref()
                .and_then(|p| p.get("target_session"))
                .and_then(|v| v.as_str())
                .unwrap_or("");
            match authz.elevate_session(&msg.session_id, target) {
                Ok(()) => "{\"status\": \"elevated\"}".to_string(),
                Err(e) => format!("{{\"status\": \"error\", \"msg\": \"{}\"}}", e),
            }
        }
        "register" => {
            let user_id = msg.payload.as_ref()
                .and_then(|p| p.get("user_id"))
                .and_then(|v| v.as_u64())
                .unwrap_or(0);
            let session = Session {
                user_id,
                role: Role::User,
                token_hash: vec![0u8; 32],
            };
            match authz.store.store_session(&msg.session_id, &session) {
                Ok(()) => "{\"status\": \"registered\"}".to_string(),
                Err(e) => format!("{{\"status\": \"error\", \"msg\": \"{}\"}}", e),
            }
        }
        _ => "{\"status\": \"unknown_action\"}".to_string(),
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Generate a random 256-bit key at startup instead of using a hardcoded key.
    let mut key = [0u8; 32];
    rand::thread_rng().fill_bytes(&mut key);
    let store = EncryptedStore::new(&key);
    let authz = Arc::new(AuthzEngine::new(store));

    let listener = TcpListener::bind("127.0.0.1:9001").await?;
    while let Ok((stream, _)) = listener.accept().await {
        let authz = authz.clone();
        tokio::spawn(async move {
            let ws_stream = accept_async(stream).await.unwrap();
            let (mut write, mut read) = ws_stream.split();
            while let Some(Ok(msg)) = read.next().await {
                if let Ok(text) = msg.to_text() {
                    if let Ok(ws_msg) = serde_json::from_str::<WsMessage>(text) {
                        let response = handle_message(&authz, &ws_msg).await;
                        let _ = write.send(tokio_tungstenite::tungstenite::Message::Text(response)).await;
                    }
                }
            }
        });
    }
    Ok(())
}
